<?php
require_once __DIR__.'/../includes/auth.php'; require_role('superadmin','finance'); require_once __DIR__.'/../includes/layout.php'; require_once __DIR__.'/../includes/lcc_payroll.php';
$kind=($_GET['kind']??$_POST['kind']??'Income')==='Deduction'?'Deduction':'Income';
$error='';$message='';
if($_SERVER['REQUEST_METHOD']==='POST'){
    require_csrf();
    try{
        $action=$_POST['action']??'';
        $conn->begin_transaction();
        if($action==='type_save'){
            $name=trim((string)($_POST['name']??''));
            if($name===''||strlen($name)>100)throw new InvalidArgumentException('Enter a type name of up to 100 characters.');
            $stmt=$conn->prepare('INSERT INTO adjustment_types(kind,name) VALUES(?,?)');$stmt->bind_param('ss',$kind,$name);
            if(!$stmt->execute())throw new DomainException('That type already exists.');
            lcc_audit($conn,'adjustment_type_created','adjustment_type',$conn->insert_id,$kind.' '.$name);$message='Type added.';
        }elseif($action==='type_toggle'){
            $typeId=(int)($_POST['type_id']??0);
            $stmt=$conn->prepare('UPDATE adjustment_types SET is_active=1-is_active WHERE type_id=? AND kind=?');$stmt->bind_param('is',$typeId,$kind);
            if(!$stmt->execute()||$stmt->affected_rows!==1)throw new DomainException('Type not found.');
            lcc_audit($conn,'adjustment_type_status','adjustment_type',$typeId,$kind);$message='Type status updated.';
        }elseif($action==='save'||$action==='void'){
            $id=(int)($_POST['adjustment_id']??0); $old=null;
            if($id>0){$stmt=$conn->prepare('SELECT * FROM payroll_adjustments WHERE adjustment_id=? FOR UPDATE');$stmt->bind_param('i',$id);$stmt->execute();$old=$stmt->get_result()->fetch_assoc();}
            if($id>0&&!$old)throw new DomainException('Adjustment not found.');
            $employeeId=$old?(int)$old['employee_id']:(int)($_POST['employee_id']??0);
            $periodId=$old?(int)$old['period_id']:(int)($_POST['period_id']??0);
            if($employeeId<=0||$periodId<=0)throw new InvalidArgumentException('Choose an employee and period.');
            $stmt=$conn->prepare("SELECT status FROM payroll_periods WHERE period_id=? FOR UPDATE");$stmt->bind_param('i',$periodId);$stmt->execute();$period=$stmt->get_result()->fetch_assoc();
            if(!$period||$period['status']!=='Draft')throw new DomainException('Only Draft periods accept adjustment changes.');
            $stmt=$conn->prepare('SELECT COUNT(*) AS total FROM payroll_records WHERE employee_id=? AND period_id=?');$stmt->bind_param('ii',$employeeId,$periodId);$stmt->execute();
            if((int)$stmt->get_result()->fetch_assoc()['total']>0)throw new DomainException('This employee already has payroll in the period. Enter or change adjustments before generating the Draft.');
            if($action==='void'){
                if(!$old||$old['status']!=='Active')throw new DomainException('Only active adjustments can be voided.');
                $stmt=$conn->prepare("UPDATE payroll_adjustments SET status='Voided' WHERE adjustment_id=?");$stmt->bind_param('i',$id);
                if(!$stmt->execute())throw new RuntimeException('Could not void adjustment.');
                lcc_audit($conn,'adjustment_voided','adjustment',$id);$message='Adjustment voided.';
            }else{
                $typeId=(int)($_POST['type_id']??0);$amount=lcc_cents($_POST['amount']??'');$description=trim((string)($_POST['description']??''));
                if($amount<=0||strlen($description)>255)throw new InvalidArgumentException('Enter a positive amount and short description.');
                $stmt=$conn->prepare('SELECT type_id FROM adjustment_types WHERE type_id=? AND kind=? AND is_active=1');$stmt->bind_param('is',$typeId,$kind);$stmt->execute();
                if(!$stmt->get_result()->fetch_assoc())throw new DomainException('Adjustment type is inactive or missing.');
                $amountSql=lcc_decimal($amount);
                if($old){if($old['status']!=='Active')throw new DomainException('Voided adjustments are locked.');$stmt=$conn->prepare('UPDATE payroll_adjustments SET type_id=?,amount=?,description=? WHERE adjustment_id=?');$stmt->bind_param('issi',$typeId,$amountSql,$description,$id);}
                else{$actor=(int)$_SESSION['admin_id'];$stmt=$conn->prepare('INSERT INTO payroll_adjustments(employee_id,period_id,type_id,amount,description,created_by) VALUES(?,?,?,?,?,?)');$stmt->bind_param('iiissi',$employeeId,$periodId,$typeId,$amountSql,$description,$actor);}
                if(!$stmt->execute())throw new RuntimeException('Could not save adjustment.');
                if(!$old)$id=$conn->insert_id;
                lcc_audit($conn,'adjustment_saved','adjustment',$id,$kind.' '.$amountSql);$message='Adjustment saved.';
            }
        }else throw new InvalidArgumentException('Unknown action.');
        $conn->commit();
    }catch(Throwable $e){$conn->rollback();$error=$e->getMessage();}
}
$types=[];$stmt=$conn->prepare('SELECT * FROM adjustment_types WHERE kind=? ORDER BY name');$stmt->bind_param('s',$kind);$stmt->execute();$typeResult=$stmt->get_result();while($row=$typeResult->fetch_assoc())$types[]=$row;
$periods=$conn->query("SELECT period_id,label,period_start,period_end FROM payroll_periods WHERE status='Draft' ORDER BY period_start DESC");
$employees=$conn->query("SELECT employee_id,employee_no,first_name,last_name FROM employees WHERE employment_status<>'Archived' ORDER BY last_name,first_name");
$stmt=$conn->prepare('SELECT a.*,t.name AS type_name,e.employee_no,e.first_name,e.last_name,pp.label AS period_label FROM payroll_adjustments a JOIN adjustment_types t ON t.type_id=a.type_id JOIN employees e ON e.employee_id=a.employee_id JOIN payroll_periods pp ON pp.period_id=a.period_id WHERE t.kind=? ORDER BY a.adjustment_id DESC');$stmt->bind_param('s',$kind);$stmt->execute();$adjustments=$stmt->get_result();
$edit=null;$editId=(int)($_GET['edit']??0);if($editId>0){$stmt=$conn->prepare('SELECT a.* FROM payroll_adjustments a JOIN adjustment_types t ON t.type_id=a.type_id WHERE a.adjustment_id=? AND t.kind=?');$stmt->bind_param('is',$editId,$kind);$stmt->execute();$edit=$stmt->get_result()->fetch_assoc();}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="icon" href="../assets/favicon.png"><title>LCC Payroll System</title><link rel="stylesheet" href="../assets/css/app.css?v=20261012-nav1"><link rel="stylesheet" href="../assets/css/apple-system.css?v=20261012-ux1"><script src="../assets/js/app.js?v=20261012-nav1" defer></script></head><body class="lcc-ux"><div class="app"><?php sidebar($kind==='Income'?'income':'deductions'); ?><main class="main"><?php topbar('Other '.$kind); ?><div class="content"><div class="page-heading"><div><div class="eyebrow">PAYROLL ADJUSTMENTS</div><h1>Other <?php echo e($kind); ?></h1><p>Itemized amounts are included once when Draft payroll is generated.</p></div><a class="btn btn-secondary" href="adjustments.php?kind=<?php echo $kind==='Income'?'Deduction':'Income'; ?>">Other <?php echo $kind==='Income'?'Deductions':'Income'; ?></a></div><div class="lcc-help-strip"><div><strong>Use this before making a Draft</strong>Add an amount only when this employee has extra pay or an extra deduction for the selected period.</div><a href="payroll_periods.php">Go to pay periods →</a></div><?php if($error): ?><div class="notice err"><?php echo e($error); ?></div><?php endif; ?><?php if($message): ?><div class="notice ok"><?php echo e($message); ?></div><?php endif; ?><section class="card form-card"><div class="card-head"><div><h2><?php echo $edit?'Edit':'Add'; ?> <?php echo e($kind); ?></h2><p>Changes close when payroll is generated for the employee and period.</p></div></div><form method="post"><?php echo csrf_field(); ?><input type="hidden" name="kind" value="<?php echo e($kind); ?>"><input type="hidden" name="action" value="save"><input type="hidden" name="adjustment_id" value="<?php echo (int)($edit['adjustment_id']??0); ?>"><div class="form-body"><div class="form-grid"><div class="field"><label>Employee</label><select name="employee_id" required <?php echo $edit?'disabled':''; ?>><option value="">Select employee</option><?php while($row=$employees->fetch_assoc()): ?><option value="<?php echo (int)$row['employee_id']; ?>" <?php echo (int)($edit['employee_id']??0)===(int)$row['employee_id']?'selected':''; ?>><?php echo e($row['employee_no'].' · '.$row['last_name'].', '.$row['first_name']); ?></option><?php endwhile; ?></select></div><div class="field"><label>Payroll period</label><select name="period_id" required <?php echo $edit?'disabled':''; ?>><option value="">Select period</option><?php while($row=$periods->fetch_assoc()): ?><option value="<?php echo (int)$row['period_id']; ?>" <?php echo (int)($edit['period_id']??0)===(int)$row['period_id']?'selected':''; ?>><?php echo e($row['label'].' · '.$row['period_start'].' – '.$row['period_end']); ?></option><?php endwhile; ?></select></div><div class="field"><label>Type</label><select name="type_id" required><option value="">Select type</option><?php foreach($types as $row): if(!$row['is_active'])continue; ?><option value="<?php echo (int)$row['type_id']; ?>" <?php echo (int)($edit['type_id']??0)===(int)$row['type_id']?'selected':''; ?>><?php echo e($row['name']); ?></option><?php endforeach; ?></select></div><div class="field"><label>Amount</label><input name="amount" type="number" min="0.01" step="0.01" required value="<?php echo e($edit['amount']??''); ?>"></div><div class="field full"><label>Description</label><input name="description" maxlength="255" value="<?php echo e($edit['description']??''); ?>"></div></div></div><div class="form-actions"><button class="btn btn-primary">Save <?php echo e($kind); ?></button><?php if($edit): ?><a class="btn btn-secondary" href="adjustments.php?kind=<?php echo e($kind); ?>">Cancel</a><?php endif; ?></div></form></section>
<section class="card"><div class="card-head"><div><h2><?php echo e($kind); ?> Types</h2></div></div><form method="post" class="toolbar"><?php echo csrf_field(); ?><input type="hidden" name="kind" value="<?php echo e($kind); ?>"><input type="hidden" name="action" value="type_save"><div><label>New type</label><input name="name" maxlength="100" required></div><button class="btn btn-secondary">Add Type</button></form><div class="table-wrap"><table class="table"><thead><tr><th>Type</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($types as $row): ?><tr><td><?php echo e($row['name']); ?></td><td><?php echo $row['is_active']?'Active':'Inactive'; ?></td><td><form method="post"><?php echo csrf_field(); ?><input type="hidden" name="kind" value="<?php echo e($kind); ?>"><input type="hidden" name="action" value="type_toggle"><input type="hidden" name="type_id" value="<?php echo (int)$row['type_id']; ?>"><button class="btn btn-secondary btn-small"><?php echo $row['is_active']?'Disable':'Enable'; ?></button></form></td></tr><?php endforeach; ?></tbody></table></div></section>
<section class="card"><div class="card-head"><div><h2>Entries</h2></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Employee</th><th>Period</th><th>Type</th><th>Amount</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php if(!$adjustments->num_rows): ?><tr><td colspan="6" class="empty">No entries.</td></tr><?php else: while($row=$adjustments->fetch_assoc()): ?><tr><td><?php echo e($row['employee_no'].' · '.$row['last_name'].', '.$row['first_name']); ?></td><td><?php echo e($row['period_label']); ?></td><td><?php echo e($row['type_name']); ?></td><td><?php echo money($row['amount']); ?></td><td><span class="badge"><?php echo e($row['status']); ?></span></td><td><?php if($row['status']==='Active'): ?><a class="btn btn-secondary btn-small" href="adjustments.php?kind=<?php echo e($kind); ?>&edit=<?php echo (int)$row['adjustment_id']; ?>">Edit</a> <form method="post" style="display:inline"><?php echo csrf_field(); ?><input type="hidden" name="kind" value="<?php echo e($kind); ?>"><input type="hidden" name="action" value="void"><input type="hidden" name="adjustment_id" value="<?php echo (int)$row['adjustment_id']; ?>"><button class="btn btn-secondary btn-small">Void</button></form><?php endif; ?></td></tr><?php endwhile; endif; ?></tbody></table></div></section></div></main></div></body></html>
